#include <iostream>
using namespace std;

int main() {
    long long n;

    while (cin >> n) {
        long long MAX = 0, MIN = 0;

        if (n / 7 == 0 && n % 7 == 6) {
            MAX = 2;
            MIN = 1;
        } else if (n / 7 > 0 && n % 7 == 0) {
            MAX = (n / 7) * 2;
            MIN = (n / 7) * 2;
        } else if (n / 7 > 0 && n % 7 == 6) {
            MAX = (n / 7) * 2 + 1;
            MIN = (n / 7) * 2;
        } else if (n / 7 > 0 && n % 7 != 6) {
            MAX = (n / 7) * 2;
            MIN = (n / 7) * 2;
        }

        cout << MIN << ' ' << MAX << '\n';
    }

    return 0;
}

