#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long weeks = n / 7;
    long long days = n % 7;

    long long minimum = weeks * 2 + max(0LL, days - 5);
    long long maximum = weeks * 2 + min(2LL, days);

    cout << minimum << ' ' << maximum << '\n';
    return 0;
}

